    # vertical rays: blocked by any 3 that is not own arm/center cell
    for r,c,col in cents:
        oa=own_arms(r,c)
        for d in (-1,1):
            i=r+d
            while 0<=i<R:
                if A[i][c]==3 and (i,c) not in oa: break
                if A[i][c]!=3: g[i][c]=col
                i+=d
    # horizontal rays: blocked by others' 3s; vertical wins (only paint empty)
    for r,c,col in cents:
        oa=own_arms(r,c)
        for d in (-1,1):
            j=c+d
            while 0<=j<C:
                if A[r][j]==3 and (r,j) not in oa: break
                if A[r][j]==0 and g[r][j]==0: g[r][j]=col
                j+=d
    # hollow: color-0 plus; vertical erase unblocked, horizontal erase loses to vertical rays
    for hr,hc in hollows:
        oa=hollow_arms
        for d in (-1,1):
            i=hr+d
            while 0<=i<R:
                if A[i][hc]==3 and (i,hc) not in oa: break
                if A[i][hc]!=3: g[i][hc]=0
                i+=d
        for d in (-1,1):
            j=hc+d
